scientific-sources.json.command:
cd /app/task_010 && python - <<'EOF'
import json
d=json.load(open('/opt/scicontext/context/scientific-sources.json'))
print(list(d.keys()))
def walk(o, path=""):
    if isinstance(o,dict):
        for k,v in o.items():
            walk(v, path+"/"+k)
    elif isinstance(o,list):
        for i,v in enumerate(o):
            walk(v, path+f"[{i}]")
    else:
        pass
# print top structure
print(json.dumps({k:(type(v).__name__, (len(v) if isinstance(v,(list,dict)) else v)) for k,v in d.items()}, indent=1)[:2000])
EOF
